from rdkit import Chem
for smi in ['*C','C*C','c1cc(*)ccc1','N(*)(*)C']:
    try:
        m=Chem.MolFromSmiles(smi)
        print(smi, 'mol', m is not None, 'atoms', m.GetNumAtoms() if m else None)
