python - <<'PY'
from rdkit import Chem
from collections import Counter
smi='C(C)(C)(C)c1cc2c(c(n3c7n(CCc5cccc(C6%10OS(=O)(=O)C(F)(F)F)n95)cc3)1)n([Fe]789%10)c1c(n4c8n6cc4)c(C(C)(C)C)cc12'
print(smi)
m=Chem.MolFromSmiles(smi, sanitize=False)
print('mol',m is not None, m.GetNumAtoms() if m else None, 'bonds', m.GetNumBonds() if m else None)
if m:
    m.UpdatePropertyCache(strict=False)
    # Check ring closure bonds all paired by no parse errors.
    for a in m.GetAtoms():
        print(a.GetIdx(),a.GetSymbol(),'deg',a.GetDegree(),'arom',a.GetIsAromatic(),'chg',a.GetFormalCharge(),'implH',a.GetNumImplicitHs())
    try:
        mh=Chem.AddHs(m)
        print('AddHs atoms', mh.GetNumAtoms(), Counter(a.GetSymbol() for a in mh.GetAtoms()))
        # count H neighbors per heavy atom for verification
        for a in mh.GetAtoms():
            if a.GetSymbol()!='H':
                h=sum(1 for nb in a.GetNeighbors() if nb.GetSymbol()=='H')
                if h or a.GetSymbol() in ('N','C','S','O','Fe','F'):
                    pass
        # print atoms with unexpected H neighbor counts maybe
        for a in mh.GetAtoms():
            if a.GetSymbol()!='H':
                h=sum(1 for nb in a.GetNeighbors() if nb.GetSymbol()=='H')
                print('heavy',a.GetIdx(),a.GetSymbol(),'deg',a.GetDegree(),'H',h,'arom',a.GetIsAromatic())
    except Exception as e:
        print('AddHs ERR',repr(e))
